{"action":"shell","command":"echo "def unique_labels(items):
    if not isinstance(items, (list, tuple)):
        raise TypeError("Input must be a list or tuple")
    cleaned = []
    for item in items:
        if not isinstance(item, str):
            raise TypeError(f"All items must be strings, got {type(item).__name__}")
        stripped = item.strip()
        if stripped:
            cleaned.append(stripped.casefold())
    unique = []
    seen = set()
    for label in cleaned:
        if label not in seen:
            seen.add(label)
            unique.append(label)
    return unique"}

